package main
import("context";"log/slog";"net/http";"os";"os/signal";"syscall";"time";"github.com/nooby6/forgequeue/internal/config";"github.com/nooby6/forgequeue/internal/database";"github.com/nooby6/forgequeue/internal/health";"github.com/nooby6/forgequeue/internal/httpserver";"github.com/nooby6/forgequeue/internal/job")
func main(){logger:=slog.New(slog.NewJSONHandler(os.Stdout,nil));cfg:=config.Load();ctx,stop:=signal.NotifyContext(context.Background(),os.Interrupt,syscall.SIGTERM);defer stop();db,err:=database.NewPool(ctx,cfg.DatabaseURL);if err!=nil{logger.Error("database_initialization_failed","error",err);os.Exit(1)};defer db.Close();repo:=job.NewPostgresRepository(db);server:=httpserver.New(cfg.Addr,&health.Handler{DB:db},job.NewHandler(job.NewService(repo)),logger);go func(){logger.Info("server_started","addr",cfg.Addr);if err:=server.ListenAndServe();err!=nil&&err!=http.ErrServerClosed{logger.Error("server_failed","error",err);stop()}}();<-ctx.Done();shutdown,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();_=server.Shutdown(shutdown)}
